import json,pathlib,hashlib,copy,uuid
ROOT=pathlib.Path.cwd(); BASE=ROOT/'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-17'; OUT=BASE/'chemie-current439-HB-materials-resources-material-author-20261017-v1';(OUT/'materials').mkdir(parents=True,exist_ok=True)
INPUT=BASE/'chemie-current439-HB37hold-term23-remediation-author-assignments-20261017-v1/INPUT.materials-resources.author-scoped.json';D=json.loads(INPUT.read_text());assert hashlib.sha256(INPUT.read_bytes()).hexdigest()=='bcce93b91a90554fce0a2424820deaa88b3ef47631b76c1cf47537b7f3155827'
C=json.loads((ROOT/D['inputPins']['C54']['path']).read_text());G={g['id']:g for g in C['goals']};P={r['goalId']:r for r in map(json.loads,(ROOT/D['inputPins']['P439']['path']).read_text().splitlines())}
def ident(p):return next(i for i in G if i.startswith(p))
def h(x):return hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def pin(p):return {'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
def save(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n');return pin(p)
def bi(de,en):return {'de':de,'en':en}
STATUS={'status':'needs_human_review','reviewAuthority':'ai_candidate','evidenceLevel':'E1','maximumClaimScope':'G1','active':False,'humanApproval':False,'actualLearnerPerformanceRecorded':False,'M7Claim':False,'ownMaterialLicense':'CC-BY-4.0'}
materials=[];refs={};changes={};newgoals=[]
def material(mid,ords,title,given,task,answer,fresh,freshanswer,rubric,extra=None):
 x={'materialId':mid,'sourceOrdinals':ords,'title':bi(*title),**STATUS,'modelAndDataOrigin':bi('Alle fiktiven Zahlen und Befunde sind eigene Unterrichtsmodelle, keine beobachtete Lernendenleistung, Produktprüfung oder Zulassung. Reale Quellen sind separat verzeichnet.','All fictional numbers and findings are own teaching models, not observed learner performance, product testing or approval. Genuine sources are listed separately.'),'givens':bi(*given),'learnerTask':bi(*task),'modelSolution':bi(*answer),'freshTransfer':{'task':bi(*fresh),'expected':bi(*freshanswer)},'rubric':bi(*rubric),'blankLearnerRecord':{'ownWork':None,'actualActionTrace':None,'sourcesActuallyRead':None,'freshTransfer':None}}
 if extra:x.update(extra)
 pp=save(OUT/'materials'/f'{mid}.DE-EN.json',x);refs[mid]=pp;materials.append(pp);return mid
def extend(prefix,mid,eid,under,perf,task,expected):
 gid=ident(prefix);r=changes.setdefault(gid,{'goalId':gid,'goalExact':copy.deepcopy(G[gid]),'profile':copy.deepcopy(P[gid]['profile']),'oldGoalPin':h(G[gid]),'oldInnerProfilePin':h(P[gid]['profile']),'addedExpectationIds':[],'addedCaseIds':[],'materialBindings':[],**STATUS});q=r['profile']
 q['expectations'].append({'id':eid,'essentialUnderstandingDe':under[0],'essentialUnderstandingEn':under[1],'observablePerformanceDe':perf[0],'observablePerformanceEn':perf[1]});q['coverageExpectations']['requiredExpectationIds'].append(eid)
 q['variationAxes'].append({'id':eid+'-transfer','textDe':'Bedingungswechsel im vollständigen Transfer selbstständig berücksichtigen.','textEn':'Independently account for changed conditions in the complete transfer.'})
 cid=mid.lower()+'-'+prefix[:4];q['applicationCaseBriefs'].append({'id':cid,'taskDemandDe':task[0],'taskDemandEn':task[1],'expectedPerformanceDe':expected[0],'expectedPerformanceEn':expected[1],'understandingFocusDe':under[0],'understandingFocusEn':under[1]});r['addedExpectationIds'].append(eid);r['addedCaseIds'].append(cid);r['materialBindings'].append({'caseId':cid,'materialId':mid,'materialPin':refs[mid],'completeMaterialIsOperative':True,'briefIsSummaryOnly':True});return r
def append_desc(r,de,en):r['goalExact']['description']+=' '+de;r['goalExact']['descriptionEn']+=' '+en
GH=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://skillpilot.com/canonical/chemistry/HB/greenhouse-radiation-balance-v1'));BTL=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://skillpilot.com/canonical/chemistry/HB/biomass-to-liquid-fischer-tropsch-v1'))
def new_atom(gid,key,title,desc,requires,mid,ords,course,under,perf):
 goal={'id':gid,'shortKey':key,'title':title[0],'titleEn':title[1],'description':desc[0],'descriptionEn':desc[1],'type':'atomic','weight':1,'tags':(['GK','LK'] if course=='GK_LK' else ['LK'])+['canonical','SekII'],'contains':[],'requires':requires,'applicability':{'jurisdiction':['DE-HB']},'dimensionTags':{'framework':'canonical-gymnasium-chemistry','demandLevel':'AB2','processCompetencies':['PK2_MODELLIEREN','PK4_KOMMUNIZIEREN','PK5_BEWERTEN'],'guidingIdeas':['BC_ENERGIE','BC_REAKTION'],'phase':'GLOBAL','area':'Energie und Rohstoffe','topicCode':key.upper()},'examples':[mid],'resourceLinks':[],'extendedData':{'applicabilityMappingInheritance':'boundary','authorProposal':{'active':False,'status':'needs_human_review','reviewAuthority':'ai_candidate','sourceContext':'HB2022 3.3','sourceCourseLevel':course,'officialTopicStatus':'mandatory_all_Q_courses_topic','selectedByLearner':None,'wholeSourceApproval':False}}}
 eid=key.replace('_','-');q={'archetype':'modeling','expectations':[{'id':eid,'essentialUnderstandingDe':under[0],'essentialUnderstandingEn':under[1],'observablePerformanceDe':perf[0],'observablePerformanceEn':perf[1]}],'coverageExpectations':{'requiredExpectationIds':[eid],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':eid+'-changed','textDe':'Neue Bedingungen im gebundenen Transfer selbstständig berücksichtigen.','textEn':'Independently account for changed conditions in the bound transfer.'}],'applicationCaseBriefs':[]}
 for kind in ['main','fresh']:
  q['applicationCaseBriefs'].append({'id':mid+'-'+kind,'taskDemandDe':'Bearbeite den vollständigen '+('Hauptfall' if kind=='main' else 'frischen Transfer')+' im gebundenen Material '+mid+'.','taskDemandEn':'Handle the complete '+('main case' if kind=='main' else 'fresh transfer')+' in bound material '+mid+'.','expectedPerformanceDe':perf[0],'expectedPerformanceEn':perf[1],'understandingFocusDe':under[0],'understandingFocusEn':under[1]})
 newgoals.append({'goalId':gid,'goalExact':goal,'profile':q,**STATUS,'uuid5':{'namespace':'uuid.NAMESPACE_URL','name':'https://skillpilot.com/canonical/chemistry/HB/'+('greenhouse-radiation-balance-v1' if gid==GH else 'biomass-to-liquid-fischer-tropsch-v1')},'parentProposal':{'parentId':'6b6bceca-e1d9-56f7-ae6c-d7f7c2fa9338','operation':'append_contains_after_review_only','active':False},'sourceBindingProposal':{'sourceOrdinals':ords,'courseLevel':course,'topicCode':'3.3','sourceInventoryPin':D['inputPins']['source232'],'officialScopeUnchanged':True,'active':False},'prerequisiteProposal':{'requires':requires,'rationaleDe':'Enge fachliche Voraussetzung der Bestands-/Wirkungskette.' if gid==GH else 'Atomerhaltung ist Voraussetzung der angegebenen Synthesebilanz.','independentGraphReviewPending':True},'semanticProposal':{'semanticKind':'curricularAtomic','active':False},'memoryProposal':{'decision':'reinforcement_optional','rationale':'Begriffsabruf ersetzt keine Bilanz-, Erklärungs- oder Transferleistung.','noActiveDeckOrCardChange':True},'imageProposal':{'status':'needs_new_image','generated':False,'need':'Kurz-/Langwellenflüsse mit Absorption/Emission.' if gid==GH else 'Biomasse→Vergasung→Reinigung→FT→Gemischaufarbeitung.'},'materialBindings':[{'materialId':mid,'materialPin':refs[mid],'completeMaterialIsOperative':True}]})
def finalize():
 for r in changes.values():
  old=P[r['goalId']]['profile'];q=r['profile'];r['newGoalPin']=h(r['goalExact']);r['newInnerProfilePin']=h(q);r['retention']={k:q[k][:len(old[k])]==old[k] for k in ['expectations','variationAxes','applicationCaseBriefs']};r['retention']['requiredExpectationIds']=q['coverageExpectations']['requiredExpectationIds'][:len(old['coverageExpectations']['requiredExpectationIds'])]==old['coverageExpectations']['requiredExpectationIds'];r['retention']['otherCoverageValues']=all(q['coverageExpectations'][k]==v for k,v in old['coverageExpectations'].items() if k!='requiredExpectationIds');assert all(r['retention'].values());r['newTaskQuotaAdded']=False
 save(OUT/'AUTHOR.whole-profile-successors.pending.json',{'role':'AUTHOR whole inner profile successors','inputPin':pin(INPUT),'inputPins':D['inputPins'],**STATUS,'records':list(changes.values()),'normalSourceActivation':False,'wholeGraphApproval':False})
 save(OUT/'AUTHOR.two-new-whole-atoms.pending.json',{'role':'AUTHOR inactive distinct new atoms',**STATUS,'records':newgoals})
 save(OUT/'MATERIALS.manifest.pending.json',{'ownCompleteMaterialPins':materials,'externalCompleteMaterialPins':[v for k,v in refs.items() if k not in [pathlib.Path(p['path']).name.removesuffix('.DE-EN.json') for p in materials]],**STATUS})
material('hb199-greenhouse-energy-climate',[199,203,92],('Energiehaushalt und Klimafolgen','Energy budget and climate consequences'),
('Eigene dimensionslose Energieflussmodelle pro gleicher Zeitspanne, keine heutigen Messwerte: Zustand I am Rand des Erdsystems einfallend 100, reflektierte kurzwellige Sonnenstrahlung 30, ausgehende langwellige Wärmestrahlung 70; netto 0. Anfangszustand II mit mehr CO2, zunächst gleicher Temperatur und gleichen Sonnen-/Reflexionsflüssen: ausgehende Wärmestrahlung 68, netto +2. Oberfläche absorbiert Einstrahlung und emittiert langwellige IR-Strahlung; Treibhausgase absorbieren/emittieren in bestimmten IR-Bereichen, auch Richtung Oberfläche. Keine spiegelnde IR-Reflexion und keine undurchlässige Einwegtür. Der natürliche Treibhauseffekt beruht auf natürlich vorhandenen Gasen, darunter Wasserdampf und CO2; menschliche Zusätze können Konzentration und Strahlungswirkung erhöhen. Fossile Verbrennung fügt dem schnellen Kreislauf Kohlenstoff hinzu. Bestandsanstieg und Strahlungswirkung sind verschiedene zu verknüpfende Schritte. Bedingungen: andere Flüsse und Albedo gehalten; keine Temperatur aus den Zahlen ableitbar.',
'Own dimensionless flux models per equal time interval, not present measurements: state I at the Earth-system boundary has incoming 100, reflected shortwave sunlight 30 and outgoing longwave thermal radiation 70; net 0. Initial state II with more CO2, initially equal temperature and unchanged solar/reflection flux: outgoing thermal radiation 68, net +2. The surface absorbs input and emits longwave IR; greenhouse gases absorb/emit in specific IR bands, also toward the surface. This is neither mirror-like IR reflection nor an impenetrable one-way door. Natural greenhouse effects involve naturally present gases including water vapour and CO2; human additions can raise concentration and radiative effect. Fossil combustion adds carbon to the fast cycle. Stock increase and radiative effect are distinct linked steps. Conditions: other fluxes/albedo held; no temperature derives from these numbers.'),
('Erkläre und zeichne den Energiehaushalt der Erde, natürlichen und anthropogenen Treibhauseffekt mit Absorption/Emission. Bilanziere beide Zustände. Beschreibe Erwärmung als Anpassung an zunächst positive Energiebilanz: ein wärmeres System kann mehr abstrahlen. Kommuniziere die Kette fossile Nutzung→CO2-Bestand→Strahlungsbilanz→Klimaänderung und mögliche Folgen wie veränderte Hitzehäufigkeit und thermische Ozeanausdehnung. Bewerte Minderung nach Wirksamkeit, Zeit, Umsetzbarkeit und Verteilung; das Schema allein ordnet keinem einzelnen Wetterereignis eine Ursache zu.',
'Explain and draw Earth energy budget and natural/anthropogenic greenhouse effects using absorption/emission. Balance both states. Describe warming as adjustment to an initially positive energy balance: a warmer system can emit more. Communicate fossil use→CO2 stock→radiation balance→climate change and possible effects such as changed heat frequency and ocean thermal expansion. Evaluate mitigation by effectiveness, timing, feasibility and distribution; this diagram alone attributes no individual weather event.'),
('I:100−30−70=0; II:100−30−68=+2, zunächst Energiespeicherung. Anthropogener Zusatz verändert die Bilanz auf Grundlage des natürlichen Effekts; er erzeugt keine Energie. Mehr CO2-Bestand allein ist noch keine Erklärung des IR-Mechanismus. Unter gehaltenen Bedingungen kann wärmere Abstrahlung eine neue Bilanz herstellen; genaue Temperatur/Zeit/regionale Folgen brauchen weitere Modelle. Weniger fossile Emissionen vermindern den weiteren Zufluss, stellen aber den alten atmosphärischen Bestand nicht sofort wieder her. Ein Urteil legt Kriterien und Bedingungen offen.',
'I:100−30−70=0; II:100−30−68=+2, initially energy storage. Human additions modify balance on top of the natural effect and create no energy. More CO2 stock alone does not explain the IR mechanism. Under held conditions warmer emission can restore balance; exact temperature/time/regional effects need further models. Lower fossil emissions reduce additional input but do not instantly restore old atmospheric stock. Judgments state criteria and conditions.'),
('Neuer Modellfall bei gleicher anfänglicher Temperatur: Reflexion steigt zugleich auf 33, ausgehende Wärme bleibt 68. Bilanziere und prüfe: Jeder CO2-Anstieg erzeugt unabhängig von allen anderen Einflüssen sofort dieselbe lokale Erwärmung. Präsentiere ein korrigiertes Kausalbild.',
'New model at equal initial temperature: reflection also rises to 33, outgoing heat remains 68. Balance and assess: every CO2 increase instantly causes the same local warming regardless of all other influences. Present a corrected causal picture.'),
('100−33−68=−1; Albedoänderung verändert die Gesamtbilanz. Sie hebt die IR-Wirkung des CO2 nicht auf, widerlegt aber die ausschließlich eindimensionale Behauptung. Globale Bilanz, Trägheit, Rückkopplungen und lokale Folgen trennen; kein sofortiger universeller Temperaturwert.',
'100−33−68=−1; changed albedo modifies total balance. It does not remove CO2 IR effects but rejects the one-dimensional claim. Distinguish global balance, inertia, feedbacks and local effects; no instant universal temperature.'),
('Drei Quellbegriffe ausdrücklich; korrekte Kurz-/Langwellenflüsse; Absorption/Emission statt Reflexion; Bestands-/Wirkungskette; begründete Folgen/Bewertung und neuer Albedotransfer.',
'Explicit three source terms; correct short/longwave flows; absorption/emission rather than reflection; stock/effect chain; reasoned effects/evaluation and new albedo transfer.'))
new_atom(GH,'hb_greenhouse_energy_balance',('Treibhauseffekt über die Strahlungsbilanz erklären','Explain the greenhouse effect through radiation balance'),('Die lernende Person kann den Energiehaushalt der Erde sowie natürlichen und anthropogenen Treibhauseffekt durch kurzwellige Einstrahlung, langwellige Absorption/Emission und Energieerhaltung erklären, fossilen CO2-Bestandsanstieg mit der Strahlungswirkung verknüpfen sowie Klimafolgen und Minderungsoptionen bedingt darstellen und begründet bewerten.','The learner can explain Earth energy budget and natural/anthropogenic greenhouse effects through shortwave input, longwave absorption/emission and energy conservation, connect fossil CO2 stock increase with radiative effects, and represent/evaluate climate effects and mitigation under stated conditions.'),[ident('0503c975')],'hb199-greenhouse-energy-climate',[199,203,92],'GK_LK',('Energiehaushalt der Erde, natürlicher und anthropogener Treibhauseffekt unterscheiden Bestand, Strahlungswirkung und Klimareaktion; der Mechanismus ist selektive Absorption/Emission, keine IR-Reflexion.','Earth energy budget and natural/anthropogenic greenhouse effects distinguish stock, radiation and climate response; the mechanism is selective absorption/emission, not IR reflection.'),('Die lernende Person erklärt und bilanziert beide Zustände, kommuniziert die Wirkungskette und bewertet Minderung bedingt; sie korrigiert ihre Folgerung beim neuen Albedofall selbstständig.','The learner explains/balances both states, communicates the causal chain and conditionally evaluates mitigation, independently revising inference in the new albedo case.'))
material('hb201-btl-fischer-tropsch',[201],('BTL über Fischer–Tropsch','BTL through Fischer–Tropsch'),
('Ausschließlich industrielles Papierschema: lignocellulosische Biomasse wie Restholz→Vergasung→rohes Synthesegas (wesentlich CO/H2 plus Verunreinigungen)→Reinigung und Einstellung H2/CO→katalytische Fischer–Tropsch-Synthese→Gemisch verschiedener Kohlenwasserstoffketten und Wasser→Abtrennung, gegebenenfalls Hydrocracken/Isomerisieren→Kraftstofffraktionen. Keine Anlage nachbauen, kein CO/H2 erzeugen. Ideales Alkanmodell n CO+(2n+1)H2→CnH2n+2+n H2O; keine gesamte Vergasungsbilanz oder Behauptung reinen FT-Produkts. Rechenfall n=8, 20 mol CO+44 mol H2, nur ideale Reaktion und vollständiger limitierender Umsatz. BTL=Biomass-to-Liquid; Kohleweg CTL, Erdgasweg GTL. BTL ist weder gepresstes Triglyceridöl noch FAME-Biodiesel. Hier Gen2-Kontext lignocellulosischer Reststoff; erste Generation meint hier Zucker/Stärke/Speiseöl geeigneter Nahrungspflanzen. LCA braucht Regeneration, Transport, Prozessenergie, Landnutzungs-/Opportunitätseffekte, Nebenprodukte und Systemgrenze.',
'Industrial paper scheme only: lignocellulosic biomass such as waste wood→gasification→raw syngas (mainly CO/H2 plus contaminants)→cleanup and H2/CO adjustment→catalytic Fischer–Tropsch synthesis→mixture of hydrocarbon chain lengths and water→separation, where needed hydrocracking/isomerization→fuel fractions. Build no plant and produce no CO/H2. Ideal alkane model n CO+(2n+1)H2→CnH2n+2+n H2O; not the complete gasification balance or a claim of pure FT product. Calculate n=8, 20 mol CO+44 mol H2, only this ideal reaction and complete limiting conversion. BTL=Biomass-to-Liquid; coal gives CTL, natural gas GTL. BTL is neither pressed triglyceride oil nor FAME biodiesel. Generation 2 here means lignocellulosic residue; first generation here means sugar/starch/edible oils of suitable food crops. LCA needs regrowth, transport, process energy, land-use/opportunity effects, coproducts and boundary.'),
('Erkläre jeden Schritt und seine Funktion. Prüfe C/H/O-Bilanz des Octanmodells, bestimme limitierenden Stoff, ideale Produkt-/Wassermenge und H2-Rest. Begründe Gemisch/Aufarbeitung, grenze BTL von Pflanzenöl/Biodiesel und Generation1 ab. Prüfe: zweite Generation ist immer CO2-neutral.',
'Explain every step and purpose. Check C/H/O balance for ideal octane; determine limiting reactant, ideal product/water and residual H2. Explain mixture/upgrading, distinguish BTL from plant oil/biodiesel and generation 1. Assess: second generation is always carbon-neutral.'),
('8 CO+17 H2→C8H18+8 H2O erhält 8 C,8 O,34 H. CO limitiert:2,5 mol ideales Octan,20 mol Wasser,42,5 mol H2 verbraucht,1,5 mol übrig. Real entstehen mehrere Kettenlängen/Nebenprodukte; selektive Ausbeute folgt daraus nicht. Reinigung schützt Katalysator; Verhältnissteuerung und Aufarbeitung liefern nutzbare Fraktionen. Nachwachsende Biomasse kann CO2 wieder aufnehmen, aber Verbrennung emittiert CO2; Gesamtneutralität ist LCA-/zeitabhängig.',
'8 CO+17 H2→C8H18+8 H2O conserves 8 C,8 O,34 H. CO limits:2.5 mol ideal octane,20 mol water,42.5 mol H2 consumed,1.5 mol left. Actual products contain several chain lengths/byproducts; selective yield does not follow. Cleanup protects catalysts; ratio adjustment/upgrading give useful fractions. Regrowing biomass can take up CO2 but combustion emits CO2; overall neutrality depends on LCA/time.'),
('Neuer Anbieter verwendet Kohle statt Holz, nennt FT-Gemisch BTL-Diesel und klimaneutral. Eingang nun 20 mol CO+34 mol H2. Prüfe Name, ideale Bilanz und Klimafazit.',
'New producer uses coal instead of wood, calls its FT mixture BTL diesel and carbon-neutral. Feed is now 20 mol CO+34 mol H2. Check naming, ideal balance and climate conclusion.'),
('Kohle bedeutet CTL, nicht BTL. H2 limitiert:2 mol ideales Octan,16 mol Wasser,4 mol CO bleiben. Reales Gemisch bleibt offen. FT macht weder Rohstoff erneuerbar noch LCA automatisch neutral.',
'Coal means CTL, not BTL. H2 limits:2 mol ideal octane,16 mol water,4 mol CO remain. Actual mixture is unresolved. FT makes neither feedstock renewable nor LCA automatically neutral.'),
('Vollständige Biomasse-/Synthesegas-/FT-/Aufarbeitungskette; korrekte Bilanz und Grenzen; BTL/FAME/CTL und Generationen; neuer limitierender Stoff; bedingte LCA.',
'Complete biomass/syngas/FT/upgrading chain; correct balance/limits; BTL/FAME/CTL and generations; new limiting reactant; conditional LCA.'))
new_atom(BTL,'hb_btl_fischer_tropsch',('BTL-Kraftstoffe über Fischer–Tropsch erklären','Explain BTL fuels through Fischer–Tropsch'),('Die lernende Person kann die Herstellung von BTL-Treibstoff aus Biomasse über Vergasung, Synthesegasreinigung/-einstellung, Fischer–Tropsch-Synthese und Gemischaufarbeitung erklären, eine angegebene ideale Synthesebilanz prüfen und den Weg von Pflanzenöl, Biodiesel und anderen Rohstoff-/Generationskontexten sowie pauschalen CO2-Neutralitätsbehauptungen abgrenzen.','The learner can explain BTL manufacture from biomass through gasification, syngas cleanup/conditioning, Fischer–Tropsch synthesis and mixture upgrading, check a specified ideal balance, and distinguish plant oil, biodiesel and other feedstock/generation contexts and blanket carbon-neutrality claims.'),[ident('11bea4c6')],'hb201-btl-fischer-tropsch',[201],'LK',('BTL verbindet Biomassevergasung, gereinigtes Synthesegas, FT-Synthese und Gemischaufarbeitung; ideale Alkanbilanz ist kein realer Selektivitäts-/LCA-Nachweis.','BTL connects biomass gasification, cleaned syngas, FT synthesis and mixture upgrading; ideal alkane balance is no actual selectivity/LCA evidence.'),('Die lernende Person erklärt die Kette, bilanziert das ideale C8-Modell mit limitierendem Stoff und unterscheidet im neuen Kohle-/H2-Fall Benennung, Stoffbilanz und Klimagrenze.','The learner explains the chain, balances ideal C8 with limiting reactant and distinguishes naming, balance and climate limits in the new coal/H2 case.'))
finalize()
print('Two new complete atoms and two bilingual complete materials written:',GH,BTL)
material('hb097-real-pla-investigation',[97],('Biobasiertes PLA tatsächlich untersuchen','Actually investigate biobased PLA'),
('Lehrkraft stellt identifizierte unbeschichtete PLA-Filmproben mit tatsächlichem Nachweis nachwachsender Rohstoffherkunft bereit. Charge, Konditionierung, Abmessungen und bekannte Zusätze sind vorab einzutragen. Kontrollierter Raumtemperatur-Vergleich unterstützter gleich breiter Streifen unter gleicher kleiner Last, keine Belastung bis zum Bruch. Startvorschlag nur nach örtlicher Freigabe: Stützweite60 mm, Breite etwa10 mm, dokumentierte unterschiedliche Dicke, zentrale Last10 g höchstens20 g, feste Halter und Auffangschale. Lehrkraft passt das an reales Material an. Keine Hitze, Schnitte oder Lösemittel; keine Heimausführung. Fehlen Freigabe/Proben, bleibt tatsächliche Durchführung offen. Keine Messwerte vorgegeben.',
'The teacher supplies identified uncoated PLA films with actual renewable-feedstock provenance. Record batch, conditioning, dimensions and known additives beforehand. Controlled room-temperature comparison of supported equal-width strips under equal small loads, no loading to fracture. Starting suggestion subject to local approval:60 mm span, about10 mm width, documented different thicknesses, central10 g load, at most20 g, secured supports and catch tray. Teacher adapts this to actual material. No heat, cutting, solvents or home execution. Missing release/samples leave actual performance open. No measured values supplied.'),
('Plane und begründe Messgröße, unabhängige Variable und Konstanten. Führe den freigegebenen Vergleich selbst durch. Dokumentiere reale Rohwerte samt Einheit, Wiederholbarkeit, Unsicherheit und Abweichungen; zeichne Aufbau und eigene Ergebnisdarstellung. Erkläre Geometrie/Werkstoffeigenschaft und prüfe, welche Herkunftsaussage der reale Nachweis trägt.',
'Plan and justify measurement, independent variable and constants. Actually perform the approved comparison yourself. Record real raw values with units, repeatability, uncertainty and deviations; draw setup and own results. Explain geometry/material property and assess which provenance claim actual documentation supports.'),
('Größere Dicke kann unter sonst gleichen Bedingungen die Biegesteifigkeit erhöhen; tatsächliche Richtung/Größe folgt nur aus eigenen Daten. Durchbiegung allein beweist weder chemisch anderes Material noch biologischen Abbau. Biobasiert beschreibt Herkunft, nicht schnellen Gewässerabbau. Modellzahlen dürfen nicht als eigene Beobachtung dienen.',
'Greater thickness can increase bending stiffness under otherwise equal conditions; actual direction/magnitude must come from own data. Deflection proves neither different chemistry nor biodegradation. Biobased describes provenance, not rapid degradation in water. Model numbers cannot stand in for own observations.'),
('Neue Probe ist dicker, anders konditioniert und enthält unbekannten Weichmacher. Darf die Durchbiegung allein der Dicke zugeschrieben werden? Entwirf kontrollierte Verbesserung; kein zusätzlicher realer Durchlauf allein wegen dieser Variation verlangt.',
'New sample is thicker, conditioned differently and contains unknown plasticizer. May deflection be attributed only to thickness? Design a controlled improvement; this variation alone imposes no extra physical trial.'),
('Nein, Zusammensetzung/Konditionierung sind Störgrößen. Gleiche Charge/Konditionierung oder kontrollierter Faktorvergleich nötig; ohne Daten bleibt die Kausalzuordnung offen.',
'No, composition/conditioning are confounders. Matched batch/conditioning or controlled factor comparison is needed; causal attribution remains unresolved without data.'),
('Eigene tatsächliche Untersuchung/Rohdaten; Kontrolle/Einheiten/Unsicherheit; Eigenschaft statt Abbaubehauptung; neuer Störgrößenfall.','Actual own investigation/raw data; control/units/uncertainty; property rather than degradation claim; new confounder case.'),{'actualExperimentRequired':True,'blankSampleAndReleaseRecord':{'release':None,'renewableProvenance':None,'dimensions':None,'actualRawMeasurements':None}})
extend('0278a515','hb097-real-pla-investigation','hb097-own-biobased-polymer-experiment',('Reale Eigenschaftsuntersuchung an identifiziertem biobasiertem PLA trennt Herkunft, Geometrie und Eigenschaft; kein Abbaunachweis.','Actual property investigation of identified biobased PLA separates provenance, geometry and property; no degradation proof.'),('Die lernende Person plant und vollzieht die freigegebene Untersuchung selbst, wertet eigene Daten mit Einheiten/Grenzen aus und bearbeitet den Störgrößentransfer.','The learner actually plans/performs the approved investigation, analyses own data with units/limits and handles confounder transfer.'),('Führe den gebundenen PLA-Vergleich tatsächlich durch und protokolliere Herkunft, Aufbau, Rohdaten und Grenzen.','Actually perform the bound PLA comparison and record provenance, setup, raw data and limits.'),('Kontrollierte Untersuchung und reale Auswertung; Konditionierung begrenzt neue Kausalaussage.','Controlled investigation and actual analysis; conditioning limits new causal inference.'))
material('hb213-additives-microplastics',[213],('Additive und Mikroplastik','Additives and microplastics'),
('Gleich dicke fiktive Folien derselben Matrix P, nur genannter Zusatz geändert: P0 ohne; P-W Weichmacher erhöht Biegsamkeit bei20°C, Migration unbekannt; P-F Farbstoff macht blau, Festigkeit gleich; P-U mineralischer Füllstoff hebt E-Modul1,0→1,6 GPa, macht undurchsichtig; P-R Flammschutz verzögert Entzündung im nur berichteten Modelltest, Rauch/Toxizität ungeprüft; P-A Antistatikum senkt Oberflächenwiderstand10^13→10^8 Ω. AuftragA flexible ableitende Elektronikablage R≤10^9 Ω; B transparente Isolierfolie R≥10^11 Ω. Partikelkarten: absichtlich hergestellte feste P-Kugeln0,7 mm; Abrieb einer8-mm-P-Folie0,7 mm; gelöste Polymerketten; reine Mineralpigmente0,7 mm. Hier häufige Arbeitsdefinition Mikroplastik: feste Kunststoffpartikel<5 mm; Regelwerksdefinitionen können abweichen. Keine Produktfreigabe.',
'Equal-thickness fictional films of same matrix P, only named additive changed: P0 none; P-W plasticizer increases flexibility at20°C, migration unknown; P-F dye gives blue colour, strength equal; P-U mineral filler raises modulus1.0→1.6 GPa, makes opaque; P-R flame retardant delays ignition in a reported model test, smoke/toxicity untested; P-A antistatic agent lowers surface resistance10^13→10^8 Ω. A:flexible dissipative electronics tray R≤10^9 Ω; B:transparent insulating film R≥10^11 Ω. Particle cards:intentionally made solid P spheres0.7 mm;0.7-mm abrasion from8-mm P film; dissolved polymer chains; pure mineral pigments0.7 mm. Common working definition here:solid plastic particles<5 mm; regulatory definitions can differ. No product clearance.'),
('Erkläre und bewerte alle fünf Additivklassen für A/B mit Nutzen, Zielkonflikten und fehlender Evidenz, ohne ungeprüft alle zu kombinieren. Verwende Additiv/Mikroplastik korrekt und ordne Partikel primär/sekundär/außerhalb ein. Trenne Entstehung/Exposition von behauptetem Gesundheitsschaden. Keine Brand-/Abriebversuche.',
'Explain/evaluate all five additive classes for A/B using benefits, trade-offs and missing evidence; do not combine all unchecked. Correctly use additive/microplastic and classify particles primary/secondary/outside. Separate formation/exposure from claimed health harm. No burning/abrasion tests.'),
('Weichmacher kann A helfen, benötigt Migrations-/Kompatibilitätsdaten; Farbstoff kennzeichnet optisch, nicht automatisch stabilisierend. Füllstoff versteift, verletzt B-Transparenz. Verzögerte Entzündung ist keine umfassende Brandsicherheit. Antistatikum erfüllt A-R, verletzt B-R. Additiv=Funktionszusatz; Mikroplastik=Material-/Partikel-/Größeneigenschaft. Kugeln primär, Abrieb sekundär; gelöste Ketten/reine Mineralien sind hier keine festen Kunststoffpartikel. Größe allein beweist keinen konkreten Gesundheitsschaden.',
'Plasticizer may help A but needs migration/compatibility data; dye gives visual identification, not automatic stabilization. Filler stiffens but violates B transparency. Delayed ignition is not overall fire safety. Antistatic agent meets A-R but violates B-R. Additive=functional addition; microplastic=material/particle/size property. Spheres primary, abrasion secondary; dissolved chains/pure minerals are not solid plastic particles here. Size alone proves no specific health harm.'),
('Neue steife transparente Lebensmittelkontaktfolie mit Nano-Füllung: Steifigkeit bekannt, Transparenz/Migration fehlen.6-mm-Plastikfragment verwittert auf2 mm. Beurteile begrenzt.',
'New stiff transparent food-contact film with nano-filling:stiffness known, transparency/migration absent.6-mm plastic fragment weathers to2 mm. Give a bounded assessment.'),
('Keine Kontaktfreigabe aus Steifigkeit; fehlende Daten prüfen.6 mm außerhalb, festes2-mm-Fragment sekundäres Mikroplastik. Nano allein beweist keine Sicherheit.',
'No contact clearance from stiffness; assess missing data.6 mm outside, solid2-mm fragment secondary microplastic. Nano alone proves no safety.'),
('Fünf korrekte Funktionen, begründete Bewertung und Datenlücken; Mikroplastik/Additiv nicht verwechseln; neuer Anwendungswechsel.','Five correct functions, reasoned evaluation and data gaps; no confusion of microplastic/additive; new application transfer.'))
extend('2652caef','hb213-additives-microplastics','hb213-additives-and-microplastics',('Fünf Zusatzklassen verändern unterschiedliche Eigenschaften; Eignung braucht Zweck/Evidenz. Mikroplastik benennt feste Kunststoffpartikel innerhalb einer angegebenen Größenabgrenzung.','Five additive classes change different properties; suitability needs purpose/evidence. Microplastic denotes solid plastic particles within a stated size boundary.'),('Die lernende Person bewertet Weichmacher, Farbstoffe, Füllstoffe, Flammschutz und Antistatika und gebraucht Additiv sowie primäres/sekundäres Mikroplastik im neuen Kontext korrekt.','The learner evaluates plasticizers, dyes, fillers, flame retardants and antistatic agents and correctly uses additive and primary/secondary microplastic in a new context.'),('Bewerte den vollständigen Additiv-/Partikelfall und die neue Kontaktfolie.','Evaluate the complete additive/particle case and new contact film.'),('Zweck, Eigenschaft und Evidenz verbinden; keine pauschale Sicherheit.','Connect purpose, property and evidence; no blanket safety.'))
material('hb208-recovery-routes',[208],('Stoffliche und energetische Verwertung','Material and energy recovery'),
('Reiner PE-Modellstrom100 kg, vereinfacht(CH2)n. M:Sortieren/Reinigen/Aufschmelzen→80 kg Granulat+20 kg Rest. C:chemisch Spalten/Aufarbeiten→70 kg gemischte organische Rohstoffe+30 kg Rest, kein fertiger Kunststoff. E:vollständige kontrollierte industrielle Verbrennung; Heizwert44 MJ/kg,20% Strom und40% tatsächlich genutzte Wärme, Rest Verluste. Inputs M/C, Emissionen, Qualität und Restbehandlung fehlen.1 kWh=3,6 MJ; M(CH2)=14 g/mol,M(CO2)=44 g/mol. Nur Papieranalyse, keine Verbrennung.',
'Pure PE model100 kg, simplified(CH2)n. M:sorting/cleaning/remelting→80 kg granulate+20 kg residue. C:chemical cleavage/work-up→70 kg mixed organic feedstock+30 kg residue, not finished polymer. E:complete controlled industrial combustion;44 MJ/kg heating value,20% electricity and40% actually useful heat, rest losses. M/C inputs, emissions, quality and residue treatment absent.1 kWh=3.6 MJ;M(CH2)=14 g/mol,M(CO2)=44 g/mol. Paper analysis only, no burning.'),
('Beschreibe werkstoffliche, rohstoffliche und energetische Wege. Bilanziere E-Energie und idealen direkten CO2-Ausstoß. Erkläre, weshalb kg Granulat/Rohstoff und Strom keine gleiche Funktion liefern. Formuliere ein bedingtes Urteil und fehlende LCA-Daten.',
'Describe mechanical, feedstock and energy routes. Balance E energy and ideal direct CO2. Explain why kg granulate/feedstock and electricity do not supply equal functions. Give a conditional judgment and missing LCA data.'),
('M erhält Polymerketten weitgehend; C erzeugt kleinere Rohstoffe; E verbraucht Polymer durch Oxidation zur Energienutzung, kein stoffliches Recycling.4400 MJ Einsatz,880 MJ=244,4 kWh Strom,1760 MJ=488,9 kWh Wärme. CH2+1,5O2→CO2+H2O;100·44/14=314,3 kg direktes CO2 ideal. Keine Lebenszyklusrangliste ohne gleiche Funktion/Systemgrenze.',
'M largely retains chains; C makes smaller feedstocks; E consumes polymer by oxidation for useful energy, not material recycling.4400 MJ input,880 MJ=244.4 kWh electricity,1760 MJ=488.9 kWh heat. CH2+1.5O2→CO2+H2O;100·44/14=314.3 kg ideal direct CO2. No LCA ranking without equal function/boundary.'),
('Neuer Abfall hat unbekannte PVC-/PE-Anteile, verschmutzte Mehrschichten und keinen Abnehmer für M-Granulat. Welche Rechnung/Folgerung bleibt tragfähig?',
'New waste has unknown PVC/PE fractions, dirty multilayers and no buyer for M granulate. Which calculation/inference remains justified?'),
('PE-Reinbilanz/Heizwert nicht übernehmen. Zusammensetzung, Sortierbarkeit, Abgasreinigung und reale Produktsubstitution klären. Stoff-/Energieunterscheidung bleibt gültig.',
'Do not transfer pure-PE balance/heating value. Resolve composition, sortability, flue-gas treatment and actual product substitution. Material/energy distinction remains valid.'),
('Drei Pfade; korrekte Einheiten/Bilanz; Funktionsvergleich; ehrlicher Gemischtransfer.','Three routes; correct units/balance; functional comparison; honest mixture transfer.'))
r=extend('8721d943','hb208-recovery-routes','hb208-energy-recovery-distinction',('Energetische Verwertung oxidiert Kunststoff zur Energienutzung und schließt keinen Stoffkreislauf; Vergleich braucht gleiche Funktion/Systemgrenze.','Energy recovery oxidizes plastic for useful energy and closes no material cycle; comparison needs equal function/boundary.'),('Die lernende Person erklärt die drei Wege, bilanziert den PE-Modellfall und begrenzt den Transfer auf unbekannte Gemische.','The learner explains three routes, balances the PE model and limits transfer to unknown mixtures.'),('Bearbeite den vollständigen PE-Stoff-/Energievergleich und neuen Mischabfall.','Handle the complete PE material/energy comparison and new mixed waste.'),('Energienutzung, Stoffrückgewinnung und LCA-Urteil unterscheiden.','Distinguish energy use, material recovery and LCA judgment.'))
append_desc(r,'Sie kann energetische Verwertung abgrenzen und deren Stoff-/Energiebilanz unter angegebenen Bedingungen beurteilen.','The learner can distinguish energy recovery and assess its material/energy balance under stated conditions.')
material('hb210-nanocomposite',[210],('Nanopartikel in Polymermatrizen','Nanoparticles in polymer matrices'),
('Gleiche fiktive Matrix/Geometrie/Temperatur:ungefüllt E=1,2 GPa,Transmission88%;5 Massen-% gut dispergiertes SiO2 E=1,8 GPa,84%;gleiche Menge agglomeriert E=1,0 GPa,55%. Vorgegeben: belastbare Grenzfläche kann Last übertragen; Agglomerate können Defekte/Lichtstreuung verstärken. Keine universelle Messreihe. Gleich dichte Kugeln:Oberfläche/Volumen=6/d. Erhaltener Nanobenetzungsfall betrifft Oberflächenchemie/Rauigkeit, dieser Fall Matrix/Grenzflächen.',
'Same fictional matrix/geometry/temperature:unfilled E=1.2 GPa,transmission88%;5 mass-% well-dispersed SiO2 E=1.8 GPa,84%;same loading agglomerated E=1.0 GPa,55%. Given:bonded interfaces can transfer load; agglomerates can increase defects/light scattering. No universal measured series. Equal-density spheres:surface/volume=6/d. Retained nanowetting case concerns surface chemistry/roughness; this case matrix/interfaces.'),
('Erkläre Eigenschaftsprofile über Grenzfläche und Dispersion; trenne Daten, Hypothese und Nachweis. Vergleiche nanopartikelverstärkte Kunststoffe ausdrücklich mit nanostrukturierten benetzbaren Oberflächen.',
'Explain properties through interfaces/dispersion; separate data, hypothesis and evidence. Explicitly compare nanoparticle-reinforced polymers with nanostructured wetting surfaces.'),
('Gut dispergiert ist hier steifer, agglomeriert trotz gleicher Menge nicht. Lastübertragung/Defekte erklären den gesetzten Trend, Tabelle isoliert Ursache nicht vollständig. Rauigkeit+Chemie beeinflusst Benetzung; Füllung beeinflusst Matrix/Grenzfläche. Nicht derselbe Einzelmechanismus und keine automatische Verbesserung.',
'Well-dispersed is stiffer here, agglomerated is not despite equal loading. Load transfer/defects explain the given trend; table does not fully isolate cause. Roughness+chemistry affects wetting; filling affects matrix/interface. Not one identical mechanism or automatic improvement.'),
('d=30 statt300 nm bei gleicher Masse/Dichte:wie ändert sich ideale Oberfläche? Darf E zehnmal1,8 GPa behauptet werden?',
'd=30 rather than300 nm at equal mass/density:how does ideal area change? May E be ten times1.8 GPa?'),
('Oberfläche Faktor10. E nicht proportional ableitbar; Haftung, Dispersion, Agglomeration und Matrix weiter nötig. Kein Zahlenwert ohne Daten.',
'Area factor10. E does not follow proportionally; adhesion, dispersion, agglomeration and matrix remain relevant. No numerical E without data.'),
('Beide Nanokontexte; Grenzfläche/Dispersion; Größenrechnung und begrenzte Kausalität.','Both nanocontexts; interface/dispersion; size calculation and bounded causality.'))
extend('dfbccd62','hb210-nanocomposite','hb210-nanoparticle-polymer-properties',('Nanopartikelverstärkung hängt von Grenzfläche/Dispersion ab; Benetzung zusätzlich von Oberflächenchemie.','Nanoparticle reinforcement depends on interfaces/dispersion; wetting additionally on surface chemistry.'),('Die lernende Person beschreibt beide Struktur-Eigenschaftskontexte und erklärt Matrixdaten sowie Grenze der Größenrechnung.','The learner describes both structure–property contexts and explains matrix data and size-scaling limits.'),('Erkläre den vollständigen Nanokompositfall und vergleiche den erhaltenen Benetzungsfall.','Explain the complete nanocomposite case and compare the retained wetting case.'),('Keine automatische Nanoverbesserung; unabhängiger Größen-/Dispersionswechsel.','No automatic nano improvement; independent size/dispersion transfer.'))
finalize()
material('hb217-dye-origins-polyenes',[217],('Farbstoffherkunft und Polyene','Dye origins and polyenes'),
('Stoffkarten: Rotkohl enthält Anthocyaningemische; Wasserextraktion/Filtration isolieren ein Gemisch ohne neue Farbstoffmoleküle zu bilden. Einzelstofftrennung braucht weitere Aufarbeitung. pH-abhängige Färbung erlaubt begrenzte Indikatornutzung. Synthetische Azofarbstoffe besitzen-N=N-; Industrieschema aromatisches Amin→Diazonium-Zwischenstufe→Kupplung mit aktiviertem Aromaten→Aufarbeitung/Formulierung. Nur Schema, kein gefährliches Arbeitsrezept. Textilnutzung braucht Faser-/Echtheitsdaten. β-Carotin kommt in Pflanzen vor, besitzt einen ausgedehnten konjugierten Polyenabschnitt und kann isoliert oder synthetisch hergestellt werden. Identität allein bestimmt nicht Reinheit/Formulierung/LCA. Polyen bedeutet mehrere C=C; nur geeignet konjugierte Abschnitte koppeln wirksam ihre π-Elektronen. Fiktiver Modellvergleich:lange konjugierte Kette absorbiert450 nm, nach sp3-Unterbrechung300 nm. Keine reale Herstellung verlangt.',
'Substance cards:red cabbage contains anthocyanin mixtures; water extraction/filtration isolate a mixture without forming new dye molecules. Single-compound separation needs further work-up. pH-dependent colour permits bounded indicator use. Synthetic azo dyes contain-N=N-; industrial scheme aromatic amine→diazonium intermediate→coupling with activated aromatic→work-up/formulation. Scheme only, no hazardous recipe. Textile use needs fibre/fastness data. β-Carotene occurs in plants, has an extended conjugated polyene segment and can be isolated or synthesized. Identity alone settles no purity/formulation/LCA. Polyene means multiple C=C; only suitably conjugated segments effectively couple π electrons. Fictional model:long conjugated chain450 nm absorption, after sp3 interruption300 nm. No actual manufacture demanded.'),
('Erläutere Vorkommen, Gewinnung bzw.Herstellung und Verwendung natürlicher/synthetischer Farbstoffe. Erhalte die Azo-, Triphenylmethan- und Anthocyaninzuordnungen. Benutze Polyene/Konjugation und erkläre den Absorptionswechsel im Energielückenmodell. Prüfe Natur=unbedenklich/nachhaltig.',
'Explain occurrence, isolation/manufacture and use of natural/synthetic dyes. Retain azo, triphenylmethane and anthocyanin classification. Use polyenes/conjugation and explain changed absorption through energy gaps. Assess natural=harmless/sustainable.'),
('Extraktion/Filtration trennen; Azokupplung bildet Moleküle. Anthocyanine und β-Carotin sind verschiedene Strukturen. Polyen ist kein Synonym für jeden Farbstoff/Naturstoff. Größere wirksame π-Kopplung kann im gegebenen Vergleich kleinere Lücke/längere Wellenlänge erklären. Polyen allein garantiert keine sichtbare Farbe. Herkunft ersetzt keine Qualitäts-/Sicherheits-/LCA-Daten.',
'Extraction/filtration separate; azo coupling forms molecules. Anthocyanins and β-carotene have different structures. Polyene is no synonym for every dye/natural substance. Greater effective π coupling can explain smaller gaps/longer wavelengths in the supplied comparison. Polyene alone guarantees no visible colour. Origin replaces no quality/safety/LCA evidence.'),
('Neues Produkt enthält identisches synthetisches statt extrahiertes β-Carotin; Reinheit/Energie fehlen. Eine weitere Kette enthält mehrere isolierte C=C. Was folgt?',
'New product contains identical synthesized rather than extracted β-carotene; purity/energy unknown. Another chain contains multiple isolated C=C. What follows?'),
('Identität begründet gleiche intrinsische Struktur, keine Zulassung/Reinheit/LCA. Isolierte C=C ergeben Polyen im weiten Strukturgebrauch, aber kein ausgedehnt konjugiertes sichtbares Chromophor. Keine genaue Farbe ohne Spektrum/Umgebung.',
'Identity supports equal intrinsic structure, not approval/purity/LCA. Multiple isolated C=C give polyene in the broad structural sense, not an extended conjugated visible chromophore. No exact colour without spectrum/environment.'),
('Beide Ursprungs-/Herstellungswege samt Verwendung; Trennung/Reaktion; Polyene bedingt; alte Klassen erhalten; neuer Qualitäts-/Konjugationsfall.',
'Both origins/manufacture and uses; separation/reaction; conditional polyenes; old classes retained; new quality/conjugation case.'))
extend('d72cbb62','hb217-dye-origins-polyenes','hb217-natural-synthetic-and-polyene',('Vorkommen, physikalische Gewinnung und Synthese unterscheiden sich; Polyene brauchen passende Konjugation für den erklärten sichtbaren Absorptionsfall.','Occurrence, physical isolation and synthesis differ; polyenes need suitable conjugation for the explained visible-absorption case.'),('Die lernende Person erklärt natürliche/synthetische Farbstoffwege und Verwendung und gebraucht Polyene am vollständigen Struktur-/Transferfall.','The learner explains natural/synthetic dye routes and uses and applies polyenes in the complete structure/transfer case.'),('Erläutere die vollständigen Anthocyanin-/Azo-/β-Carotin-Karten und den neuen Identitäts-/Konjugationsfall.','Explain complete anthocyanin/azo/β-carotene cards and new identity/conjugation case.'),('Herkunft, Klasse, Herstellung und Eignung begründet trennen.','Reason separately about origin, class, manufacture and suitability.'))
material('hb-colour-three-terms',[],('Drei Farbbegriffe bedingt verwenden','Use three colour terms conditionally'),
('Konjugiertes Modell (CH3)2N–C6H4–CH=CH–C6H4–NO2, beide Substituenten para zur Vinylbrücke. Aminisches freies Elektronenpaar kann als Donor koppeln, Nitro ist hier Akzeptor. Fiktive Spektren im gleichen Lösungsmittel:gekoppeltes Stammgerüst ohne beide Substituenten350 nm;gekoppeltes Donor/Akzeptor-System500 nm;protonierter Amindonor410 nm. Chromophor=Molekülteil, auf den der betrachtete Absorptionsübergang näherungsweise lokalisiert ist. Historischer HB-Schulgebrauch hier:gekoppelter Amindonor Auxochrom, elektronenziehender Nitro-Substituent Antiauxochrom. Keine universellen disjunkten modernen Stoffklassen:IUPAC kennzeichnet Auxochrom als überholt; Nitro kann andernorts selbst Chromophorbestandteil sein. hc=1240 eV·nm. Einzelbande bestimmt keine eindeutige vollständige Wahrnehmungsfarbe.',
'Conjugated model (CH3)2N–C6H4–CH=CH–C6H4–NO2,both substituents para to vinyl bridge. Amine lone pair can couple as donor,nitro is acceptor here. Fictional spectra in same solvent:coupled parent without both substituents350 nm;coupled donor/acceptor500 nm;protonated amine410 nm. Chromophore=molecular part on which the particular absorption transition is approximately localized. Historical HB school usage here:coupled amine donor auxochrome,electron-withdrawing nitro substituent antiauxochrome. Not universal disjoint modern classes:IUPAC labels auxochrome obsolete;nitro can itself belong to a chromophore elsewhere. hc=1240 eV·nm. A single band determines no unique full perceived colour.'),
('Nenne alle drei HB-Begriffe ausdrücklich, erkläre und markiere Rollen im Molekül, ohne Nichtüberlappung zu erfinden. Zeichne Energieniveaus, berechne Lücken350/500 nm und erkläre Protonierung unter Vorgaben. Trenne Bandverschiebung und sichere Farbbestimmung.',
'Explicitly name all three HB terms,explain/mark roles without inventing non-overlap. Draw levels,calculate gaps350/500 nm and explain protonation under the givens. Distinguish band shift from definitive colour.'),
('Gekoppeltes π-System trägt den betrachteten Chromophor; Amin=Auxochrom/Donor und Nitro=Antiauxochrom/Akzeptor in dieser historischen Konvention.1240/350=3,54 eV;1240/500=2,48 eV. Kopplung vermindert im Vergleich die relevante Lücke; Protonierung bindet das freie Paar und vermindert Donorfunktion, hier kürzere Wellenlänge. Gruppenname allein beweist keinen universellen Effekt.',
'Coupled π system carries the relevant chromophore;amine=auxochrome/donor,nitro=antiauxochrome/acceptor in this historical convention.1240/350=3.54 eV;1240/500=2.48 eV. Coupling lowers the relevant gap in this comparison;protonation binds the pair and reduces donation,giving shorter wavelength here. Group naming alone proves no universal effect.'),
('Vinylbrücke wird–CH2–CH2–;neues Modell λmax330 nm. Bleiben Fernwirkung und sichtbare gemeinsame Bande zwingend?',
'Vinyl bridge becomes–CH2–CH2–;new model λmax330 nm. Must long-range effects and joint visible band remain?'),
('Nein:sp3 unterbricht π-Kopplung. Lokale Chromophore können bleiben;gemeinsame D–π–A-Bande/Gruppenwirkungen nicht übertragen.330 nm ist UV;keine genaue sichtbare Farbe daraus.',
'No:sp3 interrupts π coupling. Local chromophores may remain;joint D–π–A band/group effects do not transfer.330 nm is UV;no exact visible colour follows.'),
('Alle Namen mit bedingten Rollen;Einheiten/Lücken;historischer Status;unabhängiger Kopplungsbruch.',
'All names with conditional roles;units/gaps;historical status;independent coupling break.'))
extend('87d8cc68','hb-colour-three-terms','hb-chromophore-explicit-use',('Chromophor ist der für eine bestimmte Bande relevante Molekülteil; Konjugation/Energielücke begrenzen die Erklärung.','Chromophore is the molecular part relevant to a particular band;conjugation/gap bound the explanation.'),('Die lernende Person benennt/lokalisiert Chromophor, berechnet Lücken und erklärt neuen Kopplungsbruch.','The learner names/locates chromophore,calculates gaps and explains a new coupling break.'),('Bearbeite den vollständigen D–π–A-Fall ausdrücklich mit Chromophor.','Handle the complete D–π–A case explicitly using chromophore.'),('Bandenbezogene Rolle und bedingte Energiefolgerung.','Band-specific role and conditional energy inference.'))
extend('64b03eff','hb-colour-three-terms','hb-auxochrome-antiauxochrome-explicit-use',('Auxochrom/Antiauxochrom sind im historischen Schulmodell gekoppelte Donor-/Akzeptorrollen, keine universellen modernen Stoffklassen.','Auxochrome/antiauxochrome are coupled donor/acceptor roles in the historical school model,not universal modern classes.'),('Die lernende Person gebraucht beide Namen am Molekül,begründet Protonierung und überträgt bei unterbrochener Konjugation begrenzt.','The learner uses both names for the molecule,explains protonation and transfers with limits after interrupted conjugation.'),('Ordne beide HB-Namen im vollständigen Fall zu und prüfe Protonierung/Brückenwechsel.','Assign both HB terms in the complete case and assess protonation/bridge change.'),('Gruppenwirkung benötigt passende Kopplung/Umgebung;historische Namen ausdrücklich erhalten.','Group effects require suitable coupling/environment;historical terms remain explicit.'))
material('hb230-actual-digital-aromatics',[230],('Aromaten selbst digital darstellen','Actually represent aromatics digitally'),
('Lehrkraft/Lernender wählt tatsächlich verfügbaren Moleküleditor mit3D-Ansicht,kein Anbieterzwang. Benzol C6H6:sechs sp2-C im geschlossenen annähernd ebenen Ring, kontinuierliches π-System. Kekulé-/aromatische Darstellung sind Modelle desselben Moleküls. Programm kann gewählte Konventionen/optimierte Geometrien zeigen;keine reale Bindungslängenmessung. Ohne Werkzeug bleibt digitale Handlung offen.',
'Teacher/learner chooses actually available molecular editor with3D view,no required vendor. Benzene C6H6:six sp2 carbons in approximately planar ring,continuous π system. Kekulé/aromatic depictions model the same molecule. Software shows conventions/optimized geometry,not actual measured bond lengths. Without tool,digital action remains open.'),
('Erstelle/prüfe Benzol tatsächlich digital;prüfe Formel/Valenzen,wechsle2D/3D,rotiere und erkläre Ringebene/π-System samt Grenzen fest eingezeichneter Doppelbindungen. Sichere eigene bearbeitbare Datei oder geeigneten Export mit nachvollziehbarer eigener Aktionsspur. Bereitgestelltes Bild ersetzt eigene Handlung nicht.',
'Actually create/check benzene digitally;check formula/valences,switch2D/3D,rotate and explain ring plane/π system and limits of fixed double bonds. Retain own editable file or suitable export with trace of own actions. Supplied image cannot replace own action.'),
('Eigenes Modell hat C6H6/korrekte Valenzen;Delokalisierung ist kein reales Bindungshinundherspringen. Werkzeug und Darstellungen begründen. Export belegt Modellhandlung,nicht Experiment/Elektronendichtemessung.',
'Own model has C6H6/correct valences;delocalization is not literal bonds jumping back and forth. Justify tool/views. Export supports modelling action,not experiment/electron-density measurement.'),
('Ändere das eigene Modell tatsächlich zu Toluol C7H8;prüfe Ringkonjugation/Valenzen und irreführende räumliche Ansicht.',
'Actually change own model to toluene C7H8;check ring conjugation/valences and misleading perspective.'),
('Methyl ersetzt Ring-H,Ring bleibt gekoppelt,C7H8. Rotation trennt Projektion und Modellgeometrie. Keine reale Messung behaupten.',
'Methyl replaces ring H,ring stays coupled,C7H8. Rotation separates projection/model geometry. Claim no actual measurement.'),
('Tatsächliche eigene Datei/Aktionen;korrekte Struktur/Modellgrenze;neuer Substitutions-/Ansichtstransfer.',
'Actual own file/actions;correct structure/model limits;new substitution/view transfer.'),{'actualDigitalActionRequired':True})
extend('707998c1','hb230-actual-digital-aromatics','hb230-own-digital-aromatic-structure',('Eigene digitale Modellhandlung erschließt Aromatenstruktur;Visualisierung ist keine Messung.','Own digital modelling explores aromatic structure;visualization is not measurement.'),('Die lernende Person bearbeitet Benzol/Toluol tatsächlich digital,prüft Valenzen/Darstellung und sichert eigene Datei/Aktionsevidenz.','The learner actually edits benzene/toluene digitally,checks valences/views and retains own file/action evidence.'),('Erzeuge und prüfe eigene digitale Aromatenmodelle im vollständigen Fall.','Create/check own digital aromatic models in the complete case.'),('Tatsächliche digitale Handlung und fachliche Darstellungsgrenzen.','Actual digital action and scientific representation limits.'))
finalize()
material('hb232-drug-society',[232],('Wirkstoffforschung historisch und heute','Drug research historically and today'),
('Historische Sachkarte:Nobelpreis Medizin1945 würdigte Fleming,Chain,Florey für Penicillin und heilende Wirkung bei verschiedenen Infektionskrankheiten. Antibakterieller Befund,Entwicklung von Wirksamkeits-/Sicherheitsnachweisen,Aufarbeitung und skalierbare Herstellung sind verschiedene Leistungen. Breitere Verfügbarkeit veränderte Behandlungsmöglichkeiten;Resistenz/ungleicher Zugang begrenzen Nutzen. Keine Behandlungsempfehlung. Fiktive heutige Förderoptionen mit ausdrücklich gleicher erwarteter Wirksamkeit im Modell:A erweitert Zugang zu geprüftem Wirkstoff,Kostenindex3,erreicht80/100 Modellbedürftige,Resistenzüberwachung enthalten;B entwickelt einen neuen antimikrobiellen Wirkstoff und plant dessen Vermarktung,Index5,erreicht50/100,Überwachung nicht finanziert. Für beide Sicherheit in definierter Zielgruppe angenommen;Umwelt-/Langzeitdaten fehlen. Keine echten klinischen Studien.',
'Historical card:1945 Nobel Medicine Prize recognized Fleming,Chain,Florey for penicillin and curative effects in various infectious diseases. Antibacterial findings,development of efficacy/safety evidence,work-up and scalable production are different achievements. Wider availability changed treatment possibilities;resistance/unequal access limit benefit. No treatment advice. Fictional current funding choices with explicitly equal expected model efficacy:A expands access to assessed drug,cost index3,reaches80/100 model people in need,resistance monitoring included;B develops a new antimicrobial active ingredient and plans its marketing,index5,reaches50/100,monitoring unfunded. Both assume safety for defined population;environmental/long-term data absent. Not actual clinical studies.'),
('Bewerte gesellschaftliche Bedeutung historisch UND aktuell anhand Nutzen,Zugang,Kosten,Sicherheit,Resistenz und Evidenzgrenzen. Unterscheide Befund,Entwicklung,großtechnische Verfügbarkeit und Werbeversprechen. Begründe eine bedingte Förderwahl;Zahlen sind keine medizinische Freigabe.',
'Evaluate societal significance historically AND today using benefit,access,cost,safety,resistance and evidence limits. Distinguish finding,development,industrial availability and marketing. Justify a conditional funding choice;numbers give no medical approval.'),
('Historischer Nutzen braucht Entwicklung,Produktion und Zugang über Entdeckung hinaus. Bei angenommener gleicher Wirkung spricht im Modell mehr Zugang,niedrigerer Index und Überwachung für A. Das Urteil legt Werte/Kriterien offen. Neue Forschung kann wichtig sein;Neuheit allein belegt weder Wirkung noch gesellschaftlichen Gesamtnutzen.',
'Historical benefit needs development,production and access beyond discovery. With assumed equal efficacy,greater access,lower index and monitoring favour A in this model. Judgment states values/criteria. New research can matter;novelty alone proves neither efficacy nor overall societal benefit.'),
('Neue Resistenzdaten machen alten Wirkstoff für einen Teil unwirksam;belastbare Vergleichsdaten für B fehlen. Übertrage die Entscheidung.',
'New resistance data make the old drug ineffective for some;robust comparative evidence for B is absent. Transfer the decision.'),
('Gleiche-Wirkung-Annahme entfällt;alte Zahlenrangfolge reicht nicht. Neue Wirksamkeits-/Sicherheitsdaten und Zielgruppenabgrenzung nötig. Forschung/Überwachung neu gewichten;B-Wirkung nicht erfinden,keine Behandlung empfehlen.',
'Equal-efficacy assumption fails;old numerical ranking no longer suffices. New efficacy/safety evidence and population definitions needed. Reweight research/monitoring;invent no B efficacy and recommend no treatment.'),
('Historischer UND aktueller Gesellschaftsbezug;Entwicklung/Produktion/Zugang;begründetes Urteil;neue Evidenz verändert Annahmen;keine klinischen Leistungsbehauptungen.',
'Historical AND current societal context;development/production/access;reasoned judgment;new evidence changes assumptions;no clinical-performance claims.'))
r=extend('3eb2a06c','hb232-drug-society','hb232-historical-current-drug-impact',('Forschung wirkt gesellschaftlich über belegte Wirkung,Entwicklung,Produktion und Zugang;historischer/heutiger Nutzen braucht Kriterien und Grenzen.','Research affects society through supported effects,development,production and access;historical/current benefit needs criteria/limits.'),('Die lernende Person bewertet historische und aktuelle gesellschaftliche Bedeutung am vollständigen Fall und revidiert Annahmen bei neuen Resistenzdaten.','The learner evaluates historical/current societal significance in the complete case and revises assumptions under new resistance evidence.'),('Bewerte die historischen und aktuellen Wirkstoffauswirkungen im vollständigen Material.','Evaluate historical/current drug impacts using the complete material.'),('Bedingtes gesellschaftliches Urteil mit Quellen-/Modellgrenzen.','Conditional societal judgment with source/model limits.'))
append_desc(r,'Sie kann historische und aktuelle gesellschaftliche Bedeutung von Wirkstoffforschung anhand Wirkung,Versorgung und offener Risiken begründet bewerten.','The learner can evaluate historical/current societal impacts of drug research using effects,access and unresolved risks.')
r['goalExact']['applicability']['jurisdiction']=list(dict.fromkeys(r['goalExact']['applicability']['jurisdiction']+['DE-HB']))
material('hb200-plant-oil-routes',[200],('Pflanzenöl gewinnen und Biotreibstoffe unterscheiden','Isolate plant oil and distinguish biofuels'),
('Industrielles Papierschema Ölfrucht→Reinigen/Zerkleinern→Pressen→Filtern/Raffinieren→Triglyceridgemisch. Optionale industrielle Lösemittelextraktion ist Trennung,keine hier auszuführende Tätigkeit. Ideal100 kg trockene Saat→30 kg Öl+70 kg Presskuchen;Saatölgehalt,Verluste/Feuchte fehlen. Pflanzenöl=Triglyceride. Biodiesel:Triglycerid+3 Methanol→3 Fettsäuremethylester+Glycerin,danach Trennung/Reinigung;keine Betriebsanweisung. Zucker-Bioethanol:C6H12O6→2 C2H5OH+2 CO2,anschließend Abtrennung;real Umsatz begrenzt. Generationenkonvention hier:1 aus Zucker/Stärke/Speiseöl geeigneter Nahrungspflanzen;2 aus lignocellulosischen bzw.benannten Reststoffpfaden. Generation ist Rohstoff-/Prozesszuordnung,keine Nachhaltigkeitsgarantie. Vollständiger BTL-FT-Prozess ist HB-LK;GK benötigt hier nur zutreffende Abgrenzung.',
'Industrial paper scheme oil crop→cleaning/crushing→pressing→filtering/refining→triglyceride mixture. Optional industrial solvent extraction is separation,not an activity to perform here. Ideal100 kg dry seed→30 kg oil+70 kg press cake;seed oil content,loss/moisture absent. Plant oil=triglycerides. Biodiesel:triglyceride+3 methanol→3 fatty-acid methyl esters+glycerol,then separation/purification;no operating instructions. Sugar bioethanol:C6H12O6→2 C2H5OH+2 CO2,then separation;actual conversion limited. Generation convention:1 from sugar/starch/edible oils of suitable food crops;2 from lignocellulosic or specified residue routes. Generation classifies feedstock/process,not guaranteed sustainability. Full BTL-FT process belongs to HB LK;GK here needs accurate distinction only.'),
('Erkläre konkrete Gewinnungs-/Herstellungsschritte auf Stoffebene. Unterscheide Pflanzenöl,Biodiesel und Bioethanol nach Rohstoff,Stoffklasse,Kernprozess. Prüfe Saatbilanz. Verwende Treibstoffe der1./2.Generation und begründe,warum erneuerbar nicht automatisch CO2-neutral ist. Erhaltene vertiefte Biodiesel-/Bioethanolprofile sind zusätzliche Carrier;keine Herstellung durchführen.',
'Explain concrete isolation/manufacturing steps at substance level. Distinguish plant oil,biodiesel and bioethanol by feedstock,class,core process. Check seed balance. Use first/second-generation fuels and explain why renewable is not automatically carbon-neutral. Retained detailed biodiesel/bioethanol profiles are additional carriers;perform no manufacture.'),
('Pressen/Filtern trennt vorhandene Triglyceride;Umesterung bildet neue Ester/Glycerin;Gärung bildet Ethanol/CO2.30+70=100 kg im idealen Saat-System;Gesamtöl-Ausbeute ohne Ölanteil nicht berechenbar. Anbau,Prozessenergie,Landnutzung,Transport,Nebenprodukte beeinflussen Klimabilanz;Auspuff emittiert auch biogenes CO2.',
'Pressing/filtering separates existing triglycerides;transesterification forms new esters/glycerol;fermentation forms ethanol/CO2.30+70=100 kg within ideal seed boundary;total oil recovery needs oil content. Cultivation,process energy,land use,transport,coproducts affect climate balance;exhaust also releases biogenic CO2.'),
('Restholz wird über Synthesegas zu Kraftstoff;anderer Anbieter nutzt gefiltertes Rapsöl. Beide heißen werblich Biodiesel und klimaneutral. Prüfe ohne neue GK-LK-Detailpflicht.',
'Waste wood becomes fuel via syngas;another producer uses filtered rapeseed oil. Both advertise biodiesel and carbon neutrality. Assess without adding LK detail duties for GK.'),
('Holz/Synthesegas passt zum zweiten Generationen-/BTL-Kontext,nicht FAME. Gefiltertes Rapsöl bleibt Pflanzenöl,keine Umesterung. Für beide keine automatische Neutralität;LCA-Systemgrenze fehlt.',
'Wood/syngas fits second-generation/BTL context,not FAME. Filtered rapeseed oil remains plant oil,no transesterification. Neither is automatically neutral;LCA boundary absent.'),
('Herstellungsschritte und Stoffklassen;richtige Bilanz/Generationen;kein Neutralitäts- oder GK/LK-Kurzschluss.',
'Manufacturing steps/classes;correct balance/generations;no neutrality or GK/LK shortcut.'))
r=extend('0959eef2','hb200-plant-oil-routes','hb200-plant-oil-production-generations',('Pflanzenöl wird physikalisch als Triglyceridgemisch gewonnen;Biodiesel/Bioethanol entstehen anders. Generationen bezeichnen Rohstoff-/Prozesskontexte.','Plant oil is physically isolated as triglyceride mixture;biodiesel/bioethanol form differently. Generations denote feedstock/process contexts.'),('Die lernende Person erklärt Gewinnungsschritte und unterscheidet Treibstoffwege/Generationen mit Bilanz und begrenztem Klimafazit.','The learner explains isolation steps and distinguishes fuel routes/generations with balance and bounded climate judgment.'),('Erläutere die vollständigen Pflanzenöl-/Biotreibstoffwege und den neuen Werbefall.','Explain complete plant-oil/biofuel routes and new advertising case.'),('Physikalische Gewinnung versus Umwandlung;Herkunft beweist keine Neutralität.','Physical isolation versus transformation;origin proves no neutrality.'))
append_desc(r,'Sie kann industrielle Gewinnung durch Pressen/Aufarbeitung erklären und erste/zweite Treibstoffgeneration nach Rohstoff/Prozess abgrenzen.','The learner can explain industrial isolation by pressing/work-up and distinguish first/second fuel generations by feedstock/process.')
material('hb098-205-real-media-research-presentation',[98,205],('Kunststoffversprechen und Klima recherchieren','Research plastic claims and climate'),
('Vollständige druckfertige eigene fiktive Medienkarte A,Hersteller BioKreis,17.10.2026:„Unsere Verpackung besteht aus erneuerbaren Rohstoffen.Deshalb ist sie überall schnell biologisch abbaubar und von Herstellung bis Entsorgung klimaneutral.“ Keine Prüfbedingungen/LCA. Vollständige fiktive Karte B,kommunales Wissenschaftsmagazin Stoffblick,17.10.2026:„Biobasierter Kohlenstoff,Abbau unter bestimmten Bedingungen und Klimabilanz sind verschiedene Fragen.Produktion benötigt Energie;Sammlung/Entsorgung beeinflussen Gesamtwirkung.Fehlende Versuchs-/Bilanzdaten erlauben keine pauschale Zusicherung.“ Redaktion,keine Produktprüfung. Keine echten Nachrichten. Reale Startpunkte:UBA-Mikroplastik und NASA-Energiehaushalt in Quellenliste;vollständiger Klimafall hb199-greenhouse-energy-climate beigefügt. Tatsächlich gedruckter Quellenbestand und echter Digitalzugang erforderlich;Karten und fachliche Ausdrucke sind erst nach realem Druck analog. Reale kontroverse Medienberichte müssen von Lernenden tatsächlich gefunden/gelesen werden.',
'Complete print-ready own fictional card A,manufacturer BioKreis,17 Oct2026:“Our packaging uses renewable feedstocks.It therefore biodegrades rapidly everywhere and is carbon-neutral from manufacture to disposal.”No test conditions/LCA. Complete fictional card B,municipal science magazine Stoffblick,same date:“Biobased carbon,degradation under specific conditions and climate balance are different questions.Production uses energy;collection/disposal affect total impact.Missing tests/balances support no blanket assurance.”Editorial,no product test. Not actual news. Real starting points:UBA microplastic and NASA energy budget in source list;complete climate case hb199-greenhouse-energy-climate attached. Actual printed holdings and digital access required;cards/technical printouts are analogue only when actually printed. Learners must actually find/read real controversial media reports.'),
('Recherchiere tatsächlich kontroverse Medienberichte über Kunststoffe aus nachwachsenden Rohstoffen im analogen Bestand UND digital. Die fiktiven Karten eröffnen die Kontroverse,ersetzen aber tatsächliche Recherche nicht. Halte Suchbegriffe,Fundort,gelesene Stelle,Urheber,Datum,Interessen,Behauptung/Beleg fest. Prüfe Informationen über nachwachsende Rohstoffe UND Klimaänderung kritisch;trenne Kohlenstoffbestand/Strahlung,Abbau und LCA. Fasse Argumente/Gegenargumente deiner tatsächlichen Funde zusammen. Präsentiere eigene Ergebnisse persönlich analog UND digital mit Quellen/Zitaten und echter Rückfrage. Fehlende Quelle,Zugang oder Zuhörer bleibt offen;keine Leistung erfinden.',
'Actually research controversial media reports on plastics from renewable feedstocks in analogue holdings AND digital media. Fictional cards introduce controversy but do not replace actual research. Record queries,location,passage read,authorship,date,interests,claim/evidence. Critically assess information about renewable resources AND climate change;separate carbon stock/radiation,degradation and LCA. Summarize arguments/counterarguments from actual findings. Personally present own results through analogue AND digital media with citations/quotations and a genuine question. Missing source,access or audience remains open;invent no performance.'),
('A vermischt drei Eigenschaften und behauptet unbelegte Universalität.B benennt passende Grenzen,muss aber ebenfalls tatsächlich geprüft werden. Institutionelle Autorität ersetzt keine Aussagepassung. CO2-Zufluss und IR-Wirkung erklären,erneuerbar=neutral reicht nicht. Erwartung ersetzt keine eigenen Fundnotizen,Argumente,Quellenurteile oder Präsentation.',
'A conflates three properties and asserts unsupported universality.B states appropriate limits but must also actually be checked. Institutional authority replaces no relevance. Explain CO2 input and IR effect;renewable=neutral is insufficient. Model answer replaces no own source notes,arguments,judgments or presentation.'),
('Neue Medienbehauptung:„Wir kaufen CO2-Zertifikate;jedes verstreute2-mm-Stück ist deshalb ohne Umweltproblem.“ Recherchiere präzisiert,prüfe Bilanzgrenze,Belegart und Mikroplastik und passe eigene Darstellung an.',
'New media claim:“We buy CO2 certificates;every littered2-mm piece therefore causes no environmental problem.”Refine actual research,check boundary,evidence type and microplastic,and adapt own representation.'),
('Kompensation beantwortet weder Partikelverbleib/Exposition noch reale Bilanz/Zusatzwirkung. Festes2-mm-Plastik erfüllt hier Mikroplastikdefinition;kein bestimmter Gesundheitsschaden allein daraus. Neue reale Funde prüfen,fehlende Daten offen.',
'Compensation settles neither particle fate/exposure nor actual balance/additionality. Solid2-mm plastic meets microplastic definition here;no particular health harm follows alone. Assess actual new findings,leave missing data open.'),
('Echte Recherche in beiden Formaten/beiden Themen;Quellenkritik/Argumente;eigene analoge/digitale Präsentation mit Interaktion;neuer Fall selbstständig.',
'Actual research in both formats/both topics;source critique/arguments;own analogue/digital presentation with interaction;independent new case.'),{'actualResearchAndPresentationRequired':True,'linkedCompleteMaterial':refs['hb199-greenhouse-energy-climate']})
for pref in ['8b98d8ba','ac8b6c0f','38e30bb9']:
 extend(pref,'hb098-205-real-media-research-presentation','hb098-205-own-controversial-resource-climate-research',('Kunststoffherkunft,Abbau und Klima benötigen verschiedene Belege;Quellenkritik/Argumente müssen aus tatsächlich analog und digital gelesenen Materialien stammen.','Plastic origin,degradation and climate need different evidence;critique/arguments must come from analogue/digital materials actually read.'),('Die lernende Person recherchiert Kontroverse/beide Themen tatsächlich analog und digital,prüft Quellen und präsentiert eigene begrenzte Ergebnisse samt echter Rückfrage.','The learner actually researches controversy/both topics through analogue/digital media,assesses sources and presents own bounded results with genuine question.'),('Recherchiere und präsentiere die vollständige Kunststoff-/Klima-Kontroverse mit eigenen Quellenhandlungen.','Research/present the complete plastic/climate controversy through own actual source actions.'),('Tatsächliche Recherche und eigene Argumente/Präsentation statt geerbter Musterleistung.','Actual research and own arguments/presentation rather than inherited model performance.'))
